       {"de": "n2alt", "a": "n4"}, {"de": "n3", "a": "n4"}, {"de": "n4", "a": "n5"}, {"de": "n5", "a": "n6"},
       {"de": "n6", "a": "n6alt", "etq": "Revisar estándar"}, {"de": "n6", "a": "n7", "etq": "Corregir operación"},
       {"de": "n6alt", "a": "n8"}, {"de": "n7", "a": "n8"}
